    float Vdc;                              // Tensão CC [V]
    uint32_t fsw_hz;                        // Frequência de comutação [Hz]
    int32_t resolution;                     // Bits do PWM LEDC (ex.: 10)
    int32_t deadtime_cycles;                // Deadtime em ciclos do timer LEDC (>=0)
    float target_phase_peak;                // Tensão-alvo pico fase-neutro [V] (0 a Vdc/2)
    uint8_t pinA, pinB, pinC;               // Pins para canais LEDC 0,1,2
    float omega_rad_per_sec;               // Frequência angular da rede [rad/s] (opcional)
    float phase_offset_global;             // Deslocamento global de fase [rad] (opcional)

    // ============================== MEMBROS INTERNOS ==============================
    bool running;
    uint32_t t_start_us;                   // Início do período atual (µs)
    uint32_t t_curr_us;                    // Tempo virtual atual (µs)
    uint32_t Ts_us;                        // Duração do período em µs

    // Estados das fases
    int8_t phase_states[3];                // +1 sup, -1 inf, 0 off
    uint64_t next_event_us[3];             // Próximo evento agendado para cada fase
    uint8_t events_per_phase[16][2];       // Lista de eventos por fase: [tempo_us, estado_novo]
    uint8_t num_events_phase[3];           // Número de eventos acumulados por fase neste período

    // Buffer global de eventos (não usado diretamente; cada fase tem sua lista)
    SVPEvent global_events[24];            // Eventos globais do período (até 24)
    uint8_t num_global_events;

    // Ponteiros para o timer fino
    volatile uint32_t g_fine_acc;          // Acumulador do timer fino (µs)
    volatile uint32_t g_fine_last;         // Último valor lido

    // ========================= CONSTRUCTORES E SETUP =========================
    explicit SVPWMHalfBridge(uint8_t pa, uint8_t pb, uint8_t pc);
    void init();                           // Configura LEDC, inicializa estados
    void start();                          // Inicia o controle
    void stop();                           // Para o controle
    void setParams(float Vdc_, uint32_t fsw_, int32_t res_, int32_t td_, float Vph_,
                   float omega_ = 0., float offset_ = 0.);
    void setDeadtime(int32_t cycles);

    // ======================= FUNÇÕES PRINCIPAIS ===============================
    /// @brief Executada a cada 1 µs pelo ISR do timer fino.
    ///        Avança o relógio virtual e aplica eventos de comutação.
    void step();

    /// @brief Executada uma vez por período (quando o período termina).
    ///        Calcula os eventos ideais de SVPWM para o próximo período.
    void computeNextPeriod();

private:
    // Constantes matemáticas
    static const float PI = 3.141592653589793;
    static const float SQRT3 = 1.732050807568877;
    static const float INV_Q3 = 1.0f / SQRT3;
    static const float HALF = 0.5f;

    // Ângulos dos 6 vetores ativos (radianos)
    static const float vec_ang[6] = {
        0.0, PI/3.0, 2.0*PI/3.0, PI.0,
        4.0*PI/3.0, 5.0*PI/3.0
    };

    // Mapa de estados de fase para cada vetor (0..5)
    static const int8_t vec_state[6][3] = {
        {1, -1, -1},   // 0°
        {1,  1, -1},   // 60°
        {-1, 1,  1},   // 120°
        {-1,-1,  1},   // 180°
        {-1, 1, -1},   // 240°
        {1, -1,  1}    // 300°
    };

    // Aloca tempos relativos aos pulsos (p1, p2, pz) para um setor
    void solveSectorAllocation(float X, float Y, float M);

    // Escreve as contagens atuais nos registradores LEDC
    void writeLeds();

    // Compensa o efeito do deadtime na tensão média (reduz alvo)
    void applyDeadtimeCompensation();
};

