// ============================ STEP () ================================
/// Avança o relógio virtual em 1 µs e processa eventos pendentes.
void SVPWMHalfBridge::step() {
    if (!running) return;

    // Advancing virtual time
    uint32_t delta = 1; // ISR garante 1 tick por chamada
    t_curr_us += delta;

    // Detectar fim de período
    if (t_curr_us >= Ts_us) {
        t_curr_us -= Ts_us;
        // Novo período começou: gerar eventos
        computeNextPeriod();
        // Marca que há novos eventos pendentes (próximos passos vão consumi-los)
        g_need_new_events = true; // membro adicionado abaixo
        return;
    }

    // Aplicar eventos que agora estão devidos
    int last_processed = 0; // será atualizado
    for (int i = 0; i < 3; i++) {
        // Verifica se o próximo evento da fase i já ocorreu
        if (g_need_apply_event(i)) {
            applyEvent(i);
        }
    }

    // Escreve contagens no LEDC
    writeLeds();
}

// ==================== COMPUTAÇÃO DE EVENTOS PARA UM PERÍODO ==========
/// Gera os eventos de SVPWM para o próximo período.
/// Deve ser chamada quando t_curr_us retorna a 0 após completar um período.
void SVPWMHalfBridge::computeNextPeriod() {
    // 1. Calcular ângulo de referência no início do período (t=0)
    float theta = phase_offset_global; // em radianos

    // 2. Discretizar o período em passos de 1 µs
    //    Como Ts_us = 50 µs para 20 kHz, o loop roda 50 vezes.
    //    Dentro dele, determinamos setores e resolvemos alocações.

    float dtheta_us = omega_rad_per_sec * 1e-6f; // variação angular por µs
    float sec_wid = PI / 3.0f; // largura de um setor

    int t_step = 0;
    float th = theta;
    int sector = getSector(th);
    int prev_sector = -1;

    // Armazena temporariamente alocações para o setor atual
    float p1 = 0., p2 = 0., pz = 0.; // frações do período

    // Loop micro a micro
    while (t_step < Ts_us) {
        // Muda de setor?
        if (sector != prev_sector || prev_sector == -1) {
            // Resolve alocação para este setor
            solveSectorAllocation(th, 0.0f, 1.0f, M); // X=th_proj, Y=0 placeholder (ver abaixo)
            // Na verdade, precisamos projetar th no sistema local
            // Vamos calcular X e Y corretamente:
            float a = vec_ang[sector]; // ângulo do vetor inferior do setor
            float X = Vref_alpha * cos(a) + Vref_beta * sin(a);
            float Y = -Vref_alpha * sin(a) + Vref_beta * cos(a);
            solveSectorAllocation(X, Y, M);

            // Vectores do setor
            int low = sector;
            int high = (sector + 1) % 6;
            // Vetor no meio (zero vector aproximado; usaremos Z+ sempre)
            float vz_a = (vec_ang[low] + vec_ang[high]) / 2.0f;

            // Tempos em µs
            uint32_t t1 = (uint32_t)(p1 * Ts_us);
            uint32_t tz = (uint32_t)(pz * Ts_us);
            uint32_t t2 = Ts_us - t1 - tz; // pode ser 0

            // Evento 1: início do setor com vetor 'low'
            if (t1 > 0 || (t1 == 0 && t2 > 0)) { // se t1=0, vai direto pro próximo
                addEventToPhase(0, 0, low, getVecState(low)); // tempo 0
            }
            // Evento 2: zero vector (se pz > 0)
            if (tz > 0) {
                addEventToPhase(0, t1, MID_ZERO_IDX, ZPLUS_STATE); // índice fictício
            }
            // Evento 3: vetor 'high'
            if (t2 > 0) {
                addEventToPhase(0, t1 + tz, high, getVecState(high));
            }
            // Ordena eventos da fase 0
            sortEventsByTime(0);
        }

        // Atualiza ângulo e setor
        th += dtheta_us;
        sector = getSector(th);
        prev_sector = sector;

        t_step++;
    }

    // Após o loop, salvamos todos os eventos por fase
    // (A função addEventToPhase preenche events_per_phase[i])
}

// ======================= AJUDANTES INTERNAS ===========================

int getSector(float th) {
    int s = (int)(th / sec_wid) % 6;
    if (s < 0) s += 6;
    return s;
}

void solveSectorAllocation(float X, float Y, float M) {
    // M é a normalização do vetor de referência (0 a ~0.866 para sinusoidal)
    // Aqui estamos trabalhando com X,Y já escalados para M=1? Precisamos ajustar.
    // Na prática, calculamos M alvo e usamos como referência.
    // Para simplificar, assumimos que X,Y já estão em unidades de Vm (raio do hexágono).
    // Vamos resolver p1,p2,pz sem depender de M diretamente, mas usando X,Y como projeções.
    // A equação correta considera que queremos atingir M*Vr onde Vr é o raio do hexágono.
    // Mas para manter simples, vamos usar o método de projeção direta.
    // Deixe-me definir constants:
    float sq3 = SQRT3;
    float inv_sq3 = INV_Q3;
    float qhalf = HALF;
    // Coeficientes derivados
    float c1 = 0.5f; // cos60
    float c2 = sq3 * 0.5f; // sin60
    float c3 = sq3 * 0.5f; // cos30 (para zero vector)
    float c4 = 0.5f; // sin30

    // Equações:
    // X = p1 + 0.5 p2 + 0.5*sqrt3 * pz   (porque c3=cos30=0.866, mas aqui normalizamos? Vamos reescalonar)
    // Na verdade, as componentes dos vetores em unidades de Vm são:
    // V1 = (1, 0)
    // V2 = (0.5, sqrt3/2)
    // Vz = (sqrt3/2, 0.5)  (direção do zero vector Z+)
    // Então:
    // X = p1*1 + p2*0.5 + pz*(sqrt3/2)
    // Y = p1*0 + p2*(sqrt3/2) + pz*0.5
    // p1 + p2 + pz = 1

    // Solução:
    // Da eq Y: p2 = (Y - 0.5*pz) * (2/sqrt3)
    float p2_coef_Y = (2.0f / sq3); // fator para Y
    float one_over_two_sq3 = 1.0f / (2.0f * sq3);

    float p2_expr = p2_coef_Y * (Y - 0.5f * pz);

    // Substituindo na eq X:
    // X = (1 - p2 - pz) + 0.5*p2 + (sqrt3/2)*pz
    // => X = 1 - 0.5*p2 - pz + (sqrt3/2)*pz
    // => 1 - X = 0.5*p2 + pz*(1 - sqrt3/2)
    float rhs_const = 1.0f - X;
    float coeff_pz = (1.0f - sqrt3 * 0.5f); // = (2-sqrt3)/2 ≈ 0.13397

    // Agora: rhs_const = 0.5*p2 + coeff_pz*pz
    // E p2 = p2_coef_Y*(Y - 0.5*pz)
    // Substituindo:
    // rhs_const = 0.5 * p2_coef_Y * (Y - 0.5*pz) + coeff_pz * pz
    // => rhs_const - (0.5 * p2_coef_Y * Y) = pz * (coeff_pz + 0.5 * p2_coef_Y * 0.5)
    // Nota: 0.5 * p2_coef_Y * 0.5 = 0.5^2 / sqrt3 = 0.25/sqrt3
    // Vamos calcular numericamente para evitar erros:
    float term_y = 0.5f * p2_coef_Y * Y; // = Y / (sqrt3)
    float coeff_pz_total = coeff_pz + 0.5f * one_over_two_sq3; // = 0.13397 + 0.14434 = 0.27831
    // Espera, vamos refazer: 0.5 * p2_coef_Y * 0.5 = 0.25 / sqrt3 = 0.14434
    // Então coeff_pz_total = coeff_pz + 0.14434 = 0.13397 + 0.14434 = 0.27831
    // Mas antes eu tinha outro valor; vou seguir essa derivação correta agora.

    // Reorganizando:
    // rhs_const - term_y = pz * (coeff_pz + 0.25/sqrt3)
    // Let A = rhs_const - term_y
    // Let B = coeff_pz + 0.25f/sqrt3
    // pz = A / B

    float A_val = rhs_const - term_y;
    float B_val = coeff_pz + (0.25f / sq3); // = 0.27831
    pz = A_val / B_val;

    // Garante pz entre 0 e 1 (pode requerer clamp leve)
    if (pz < 0) pz = 0;
    if (pz > 1) pz = 1;

    p2 = (p2_coef_Y * (Y - 0.5f * pz));
    p1 = 1.0f - p2 - pz;
    if (p1 < 0) p1 = 0; // fallback (raro)
    if (p2 < 0) p2 = 0;
    if (p1 > 1 - p2 - pz) p1 = 1.0f - p2 - pz;

    // Ajuste fino para garantir soma = 1
    float sum_check = p1 + p2 + pz;
    float delta_p = (1.0f - sum_check); // pequena correção distribuída igualmente
    p1 += delta_p / 3.0f;
    p2 += delta_p / 3.0f;
    pz += delta_p / 3.0f;
    // Reaplicar clamps se necessário (geralmente ok)
}

// ========================== GERENCIAMENTO DE EVENTOS ===================

void addEventToPhase(int phase, uint32_t time_offset_us, int vec_idx, int8_t state[]) {
    // Guarda no buffer global e depois redistribui para a lista da fase
    // Para simplicidade, faremos uma abordagem mais direta:
    // Em vez de buffers complicados, mantemos um ponteiro para o próximo evento
    // de cada fase e verificamos se ele chegou.
    // Como estamos em nível de algoritmo, deixarei isso como pseudo-código detalhado:
    //
    // Exemplo de como preencher events_per_phase[phase]:
    //   if (num_events_phase[phase] < 16) {
    //       events_per_phase[phase][num_events_phase[phase]-1] = {time_offset_us, state};
    //       num_events_phase[phase]++;
    //   }
    // Depois ordena por tempo.
    //
    // Na implementação real, faça isso dentro de computeNextPeriod().
}

// Funções auxiliares para aplicar eventos
bool SVPWMHalfBridge::g_need_apply_event(int phase) {
    // Se há eventos pendentes cujo tempo <= t_curr_us
    // Como eventos são armazenados em ordem crescente, basta olhar o primeiro
    if (num_events_phase[phase] > 1) { // 1 é o evento inicial placeholder
        return events_per_phase[phase][0].time_us <= t_curr_us;
    }
    return false;
}

void SVPWMHalfBridge::applyEvent(int phase) {
    const SVPEvent& ev = events_per_phase[phase][0]; // deve estar no início devido à ordenação
    uint64_t next_after = ev.time_us + ev.next_duration_us; // próxima duração (calculada ao adicionar)

    // Calcula tempo desde a última comutação até este evento
    uint64_t dur_us = ev.time_us - last_switch_us[phase];
    if (dur_us <= 0) dur_us = 0; // se perdido, trata como imediato

    // Atualiza contagem LEDC desta fase
    uint32_t count = (uint32_t)(dur_us * fsw_hz / 1000000.0f);
    ledcWrite(0, count); // canal 0 = fase A (aproximação: canal corresponde ao pin)
    // Atenção: cada fase usa um canal LEDC diferente. Ajuste conforme pinA/B/C.

    // Atualiza estado da fase
    phase_states[phase] = ev.state[phase]; // estado novo

    // Marca comutação
    last_switch_us[phase] = t_curr_us;
    switched[phase] = true;

    // Agenda o próximo evento, se houver
    if (ev.index + 1 < num_events_phase[phase]) {
        uint64_t next_time = events_per_phase[phase][ev.index + 1].time_us;
        next_event_us[phase] = next_time;
    } else {
        next_event_us[phase] = UINT64_MAX; // sem evento futuro neste período
    }
}

// ==================== ESCREVENDO LEDC ================================
void SVPWMHalfBridge::writeLeds() {
    for (int i = 0; i < 3; i++) {
        uint32_t count = 0;
        if (next_event_us[i] != UINT64_MAX) {
            // Tempo desde a última comutação até o próximo evento
            uint64_t dur = next_event_us[i] - (last_switch_us[i] == UINT64_MAX ? t_curr_us : last_switch_us[i]);
            if (dur <= 0) dur = t_curr_us; // se perdido, assume todo o período
            count = (uint32_t)(dur * fsw_hz / 1000000.0f);
        } else {
            // Sem evento futuro: manter ocupado até o fim do período
            count = (uint32_t)(Ts_us * fsw_hz / 1000000.0f);
        }
        // Associe ao canal correto
        if (i == 0) ledcWrite(0, count); // canal 0 -> pinA
        else if (i == 1) ledcWrite(1, count); // canal 1 -> pinB
        else ledcWrite(2, count); // canal 2 -> pinC
    }
}

